"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[2666],{5158(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>a,toc:()=>d});var a=n(6488),o=n(4848),i=n(8453);const s={slug:"first-homelab",title:"My first homelab",date:new Date("2026-04-19T00:00:00.000Z"),authors:["Nathan"],tags:["networking","linux"]},r=void 0,l={authorsImageUrls:[void 0]},d=[{value:"Intro",id:"intro",level:2},{value:"Hardware",id:"hardware",level:3},{value:"Installing proxmox",id:"installing-proxmox",level:3},{value:"Remote Access via tailscale tunnel",id:"remote-access-via-tailscale-tunnel",level:2},{value:"Organization and network design",id:"organization-and-network-design",level:3},{value:"Conclusion",id:"conclusion",level:2}];function h(e){const t={a:"a",h2:"h2",h3:"h3",img:"img",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h2,{id:"intro",children:"Intro"}),"\n",(0,o.jsx)(t.p,{children:"Around December 2025, I was in the market for a new laptop. My current laptop was alright, my main issue was the relatively small SSD and outdated cpu. Still, it had 16gb of ddr4. Around that same time, I had began doing research into homelabs, and self hosting different services. When Christmas came around and I had a new laptop, instead of retiring the old laptop and letting it collect dust, I opted to re-purpose it into a homelab!"}),"\n",(0,o.jsx)(t.p,{children:"When I began this project, I did not have a concrete plan. However, I did have a starting goal of setting up a minecraft server, and a self-hosted markdown editor. Since I wanted multiple services running, and planned to add more in the future, I wanted to install a type 1 bare-metal hypervisor on the laptop. The hypervisor I chose was Proxmox."}),"\n",(0,o.jsx)(t.h3,{id:"hardware",children:"Hardware"}),"\n",(0,o.jsx)(t.p,{children:"The specifications for my laptop turned homelab are as follows:"}),"\n",(0,o.jsx)(t.p,{children:"AMD Ryzen 7 5700U\n16gb DDR4\n256gb"}),"\n",(0,o.jsx)(t.p,{children:"Although not typical hardware for this application, this was a way for me to dip my toes in the water."}),"\n",(0,o.jsx)(t.h3,{id:"installing-proxmox",children:"Installing proxmox"}),"\n",(0,o.jsx)(t.p,{children:"To install proxmox on my laptop, I first downloaded the ISO from the official proxmox website, and flashed it onto a usb stick with Rufus."}),"\n",(0,o.jsx)(t.p,{children:"Before continuing, I went through everything on my laptop and backed up all important data to an external ssd. Once that was done, I plugged in the USB, booted into the BIOS, and selected to boot from the usb. The proxmox installation was graphical and straight forward. It allowed me to specifiy my gateway IP, and the static IP for proxmox. After installation was complete, I connected to the web interface by entering the static IP into my browser and specifying the correct port."}),"\n",(0,o.jsx)(t.h2,{id:"remote-access-via-tailscale-tunnel",children:"Remote Access via tailscale tunnel"}),"\n",(0,o.jsx)(t.p,{children:"An important aspect of any server is how you access it. I chose to not expose any ports to the open internet, as this would be a dangerous thing to do for a beginner. Instead, I went with tailscale. Tailscale allowed me to setup a tunnel to my server, allowing secure remote access."}),"\n",(0,o.jsx)(t.h3,{id:"organization-and-network-design",children:"Organization and network design"}),"\n",(0,o.jsx)(t.p,{children:"The next step in the process was planning out how everything would be organized. The services I wanted were as follows: A minecraft server, Docmost, nginx proxy manager, and navidrome."}),"\n",(0,o.jsxs)(t.p,{children:["For the first 3, I used pve containers, and deployed them using scripts found on ",(0,o.jsx)(t.a,{href:"https://community-scripts.org",children:"https://community-scripts.org"}),". The minecraft server, and docmost worked right out of the box, but nginx proxy manager required some configuring. The purpose of this service was to allow connection through dns, but only on my local network. For example, docs.splatty.org would resolve to docmost, and play.splatty.org would resolve to the minecraft server. I had to learn about dns records, how to assign my own ssl certificates, and do some configuring on the cloudflare portal. But after all that, it was functioning properly."]}),"\n",(0,o.jsx)(t.p,{children:"Navidrome was a bit more involved. Instead of using a pre-made script, I wanted to manually install the service using docker. Although the pre-made scripts were convenient, I felt that I was missing out on a valuable opportunity by taking the 'easy way'."}),"\n",(0,o.jsx)(t.p,{children:"The network design phase was quite simple. I wanted to plan out how I would lay out future additions to the server. The design I used was quite simple, Proxmox was on 192.168.4.1, the minecraft server was on 192.168.4.101, nginx proxy manager was on 192.168.4.102, etc. This allowed addressable space to be available for an ample amount of future needs. Below is a diagram that shows how my network was setup."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{src:n(9160).A+"",width:"1038",height:"862"})}),"\n",(0,o.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,o.jsx)(t.p,{children:"This was an incredibly rewarding project that not only let me setup some cool self hosted services, but also taught me a lot about networking in the process. Through every roadblock and solution I encountered, I gained a little bit more knowledge. This is a project that I would recommend to anyone in IT. It teaches you fundamental information about networking that will broaden your understanding of how this technology works."}),"\n",(0,o.jsx)(t.p,{children:"As I am writing this, I currently have plans on upgrading and transferring these services to a proper server that I acquired at an estate sale. I am having some hardware issues with it at the moment, so it may be a long while until I get it operational."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},9160(e,t,n){n.d(t,{A:()=>a});const a=n.p+"assets/images/homelab_diagram-847c8f32be44af634ccfc271e9cbfefd.png"},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(6540);const o={},i=a.createContext(o);function s(e){const t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}},6488(e){e.exports=JSON.parse('{"permalink":"/blog/first-homelab","source":"@site/blog/Homelab moment.md","title":"My first homelab","description":"Intro","date":"2026-04-19T00:00:00.000Z","tags":[{"inline":false,"label":"Networking","permalink":"/blog/tags/networking","description":"Networking posts"},{"inline":false,"label":"Linux","permalink":"/blog/tags/linux","description":"Linux posts"}],"readingTime":3.62,"hasTruncateMarker":false,"authors":[{"name":"Nathan Bledsoe","title":"Cybersecurity student","url":"https://www.linkedin.com/in/nathan-bledsoe-07b9b63b2/","page":{"permalink":"/blog/authors/all-my-articles"},"socials":{"github":"https://github.com/nathanb527","linkedin":"https://www.linkedin.com/in/nathan-bledsoe-cyber/"},"imageURL":"/img/me.jpg","key":"Nathan"}],"frontMatter":{"slug":"first-homelab","title":"My first homelab","date":"2026-04-19T00:00:00.000Z","authors":["Nathan"],"tags":["networking","linux"]},"unlisted":false,"nextItem":{"title":"Secure Password Manager Writeup","permalink":"/blog/secure-password-manager"}}')}}]);